60	function buildPolicyOptions(plugins?: RedteamPluginObject[]): string[] {
61	  const policyIds = new Set<string>();
62	  plugins?.forEach((plugin) => {
63	    if (typeof plugin !== 'string' && plugin.id === 'policy') {
64	      const policy = plugin?.config?.policy;
65	      if (policy) {
66	        if (isValidPolicyObject(policy)) {
67	          policyIds.add(policy.id);
68	        } else {
69	          policyIds.add(makeInlinePolicyId(policy));
70	        }
71	      }
72	    }
73	  });
74	
75	  return Array.from(policyIds).sort();
