97	function DebouncedTextField({
98	  value,
99	  onChange,
100	  ...props
101	}: {
102	  value: string;
103	  onChange: (value: string) => void;
104	  [key: string]: any;
105	}) {
106	  const [localValue, setLocalValue] = useState(value);
107	  const [debouncedValue] = useDebounce(localValue, 500);
108	
109	  // Update parent when debounced value changes
110	  useEffect(() => {
111	    if (debouncedValue !== value) {
112	      onChange(debouncedValue);
113	    }
114	  }, [debouncedValue, value, onChange]);
115	
116	  // Sync with external value changes
117	  useEffect(() => {
118	    setLocalValue(value);
119	  }, [value]);
120	
121	  return (
122	    <TextField
123	      {...props}
124	      value={localValue}
125	      onChange={(e) => setLocalValue(e.target.value)}
126	      sx={{
127	        '& .MuiInputBase-input': {
128	          py: 1,
129	        },
130	        ...props.sx,
131	      }}
132	    />
133	  );
134	}
