70	
71	  // Build base query with efficient filtering
72	  let baseQuery = sql`eval_id = ${evalId}`;
73	
74	  // Add mode filter (these can use indexes)
75	  if (mode === 'errors') {
76	    baseQuery = sql`${baseQuery} AND failure_reason = ${2}`; // ResultFailureReason.ERROR
77	  } else if (mode === 'failures') {
78	    baseQuery = sql`${baseQuery} AND success = 0 AND failure_reason != ${2}`;
79	  } else if (mode === 'passes') {
80	    baseQuery = sql`${baseQuery} AND success = 1`;
81	  } else if (mode === 'highlights') {
82	    baseQuery = sql`${baseQuery} AND json_extract(grading_result, '$.comment') LIKE '!highlight%'`;
83	  }
84	
