86	  // This is a compromise - we search less fields but query is faster
87	  let searchCondition = sql`1=1`;
88	  if (opts.searchQuery && opts.searchQuery.trim() !== '' && !opts.filters?.length) {
89	    const sanitizedSearch = opts.searchQuery.replace(/'/g, "''");
90	    // Only search in response field for better performance
91	    searchCondition = sql`response LIKE ${'%' + sanitizedSearch + '%'}`;
92	  }
93	
94	  const whereClause = sql`${baseQuery} AND ${searchCondition}`;
95	
96	  // Get filtered count using the composite index
97	  const countStart = Date.now();
98	  const countQuery = sql`
99	    SELECT COUNT(DISTINCT test_idx) as count 
100	    FROM ${evalResultsTable} 
101	    WHERE ${whereClause}
102	  `;
103	
104	  const countResult = await db.all<{ count: number }>(countQuery);
105	  const filteredCount = Number(countResult[0]?.count ?? 0);
106	  logger.debug(`Optimized count query took ${Date.now() - countStart}ms`);
107	
108	  // Get test indices
109	  const idxStart = Date.now();
110	  const idxQuery = sql`
111	    SELECT DISTINCT test_idx 
112	    FROM ${evalResultsTable} 
113	    WHERE ${whereClause}
114	    ORDER BY test_idx 
115	    LIMIT ${limit} 
116	    OFFSET ${offset}
117	  `;
118	
119	  const rows = await db.all<{ test_idx: number }>(idxQuery);
120	  const testIndices = rows.map((row) => row.test_idx);
121	  logger.debug(`Optimized index query took ${Date.now() - idxStart}ms`);
122	
123	  return { testIndices, filteredCount };
124	}
