+const Database = require('better-sqlite3');
+const db = new Database(':memory:');
+db.exec("CREATE TABLE t (id INTEGER, metadata TEXT)");
+const rows = {
+  present_str: '{"f":"hello"}',
+  empty_str: '{"f":""}',
+  ws_str: '{"f":"   \t\n "}',
+  num_zero: '{"f":0}',
+  bool_false: '{"f":false}',
+  empty_arr: '{"f":[]}',
+  empty_obj: '{"f":{}}',
+  json_null: '{"f":null}',
+  absent: '{"g":1}',
+};
+let i = 0; const ids = {};
+for (const [k,v] of Object.entries(rows)) { i++; ids[i]=k; db.prepare("INSERT INTO t VALUES (?,?)").run(i, v); }
+const fieldPath = `'$."f"'`;
+const ws = 'char(32) || char(9) || char(10) || char(13) || char(12) || char(11)';
+const cond = `(json_type(metadata, ${fieldPath}) IS NOT NULL AND json_type(metadata, ${fieldPath}) != 'null' AND (json_type(metadata, ${fieldPath}) != 'text' OR TRIM(json_extract(metadata, ${fieldPath}), ${ws}) != ''))`;
+const matched = db.prepare(`SELECT id FROM t WHERE ${cond}`).all().map(r=>ids[r.id]);
+console.log("MATCHED:", matched.sort().join(', '));
+const expected = ['present_str','num_zero','bool_false','empty_arr','empty_obj'].sort().join(', ');
+console.log("EXPECTED:", expected);
+console.log(matched.sort().join(', ') === expected ? "PASS" : "FAIL");
