t ${maxCount}. `;\n    reason += `Errors: ${errorDetails.join(', ')}`;\n    if (errorSpans.length > 3) {\n      reason += ` and ${errorSpans.length - 3} more`;\n    }\n  } else if (maxPercentage !== undefined && errorPercentage > maxPercentage) {\n    pass = false;\n    reason = `Error rate ${errorPercentage.toFixed(1)}% exceeds threshold ${maxPercentage}% `;\n    reason += `(${errorCount} errors out of ${matchingSpans.length} spans)`;\n  } else {\n    if (errorCount === 0) {\n      reason = `No errors found in ${matchingSpans.length} spans matching pattern \"${pattern}\"`;\n    } else {\n      reason = `Found ${errorCount} error(s) in ${matchingSpans.length} spans (${errorPercentage.toFixed(1)}%)`;\n      if (maxCount !== undefined) {\n        reason += `, within threshold of ${maxCount}`;\n      }\n      if (maxPercentage !== undefined) {\n        reason += `, within threshold of ${maxPercentage}%`;\n      }\n    }\n  }\n\n  return {\n    pass,\n    score: pass ? 1 : 0,\n    reason,\n    assertion,\n  };\n};\n"],"names":["handleTraceErrorSpans","matchesPattern","spanName","pattern","regexPattern","replace","regex","RegExp","test","isErrorSpan","span","statusCode","attributes","errorKeys","key","statusMessage","errorPatterns","assertion","context","trace","spans","Error","value","maxCount","maxPercentage","Array","isArray","objValue","max_count","max_percentage","undefined","matchingSpans","filter","name","length","pass","score","reason","errorSpans","errorCount","errorPercentage","errorDetails","slice","map","detail","join","toFixed"],"mappings":";;;;+BAiEaA;;;eAAAA;;;AAxDb,SAASC,eAAeC,QAAgB,EAAEC,OAAe;IACvD,qCAAqC;IACrC,MAAMC,eAAeD,QAClBE,OAAO,CAAC,qBAAqB,QAAQ,6BAA6B;KAClEA,OAAO,CAAC,OAAO,MAAM,kBAAkB;KACvCA,OAAO,CAAC,OAAO,MAAM,iBAAiB;IAEzC,MAAMC,QAAQ,IAAIC,OAAO,CAAC,CAAC,EAAEH,aAAa,CAAC,CAAC,EAAE;IAC9C,OAAOE,MAAME,IAAI,CAACN;AACpB;AAEA,SAASO,YAAYC,IAAe;IAClC,oDAAoD;IACpD,IAAIA,KAAKC,UAAU,IAAID,KAAKC,UAAU,IAAI,KAAK;QAC7C,OAAO;IACT;IAEA,qCAAqC;IACrC,IAAID,KAAKE,UAA