+{"version":3,"sources":["/workspace/repo/src/globalConfig/accounts.ts"],"sourcesContent":["import { randomUUID } from 'crypto';\n\nimport input from '@inquirer/input';\nimport chalk from 'chalk';\nimport { z } from 'zod';\nimport { TERMINAL_MAX_WIDTH } from '../constants';\nimport { getEnvString, isCI } from '../envars';\nimport logger from '../logger';\nimport { fetchWithTimeout } from '../util/fetch/index';\nimport { readGlobalConfig, writeGlobalConfig, writeGlobalConfigPartial } from './globalConfig';\n\nimport type { GlobalConfig } from '../configTypes';\n\nexport function getUserId(): string {\n  let globalConfig = readGlobalConfig();\n  if (!globalConfig?.id) {\n    const newId = randomUUID();\n    globalConfig = { ...globalConfig, id: newId };\n    writeGlobalConfig(globalConfig);\n    return newId;\n  }\n\n  return globalConfig.id;\n}\n\nexport function getUserEmail(): string | null {\n  const globalConfig = readGlobalConfig();\n  return globalConfig?.account?.email || null;\n}\n\nexport function setUserEmail(email: string) {\n  const config: Partial<GlobalConfig> = { account: { email } };\n  writeGlobalConfigPartial(config);\n}\n\nexport function getAuthor(): string | null {\n  return getEnvString('PROMPTFOO_AUTHOR') || getUserEmail() || null;\n}\n\nexport function isLoggedIntoCloud(): boolean {\n  const userEmail = getUserEmail();\n  return !!userEmail && !isCI();\n}\n\ninterface EmailStatusResult {\n  status: 'ok' | 'exceeded_limit' | 'show_usage_warning' | 'no_email';\n  message?: string;\n  email?: string;\n  hasEmail: boolean;\n}\n\n/**\n * Shared function to check email status with the promptfoo API\n * Used by both CLI and server routes\n */\nexport async function checkEmailStatus(): Promise<EmailStatusResult> {\n  const userEmail = isCI() ? 'ci-placeholder@promptfoo.dev' : getUserEmail();\n\n  if (!userEmail) {\n    return {\n      status: 'no_email',\n      hasEmail: false,\n      message: 'Redteam evals require email verification. Please enter your work email:',\n    };\n  }\n\n  try {\n    const resp = await fetchWithTimeout(\n      `https://api.promptfoo.app/api/users/status?email=${encodeURIComponent(userEmail)}`,\n      undefined,\n      500,\n    );\n    const data = (await resp.json()) as {\n      status: 'ok' | 'exceeded_limit' | 'show_usage_warning';\n      message?: string;\n      error?: string;\n    };\n\n    return {\n      status: data.status,\n      message: data.message,\n      email: userEmail,\n      hasEmail: true,\n    };\n  } catch (e) {\n    logger.debug(`Failed to check user status: ${e}`);\n    // If we can't check status, assume it's OK but log the issue\n    return {\n      status: 'ok',\n      message: 'Unable to verify email status, but proceeding',\n      email: userEmail,\n      hasEmail: true,\n    };\n  }\n}\n\nexport async function promptForEmailUnverified() {\n  const { default: telemetry } = await import('../telemetry');\n  let email = isCI() ? 'ci-placeholder@promptfoo.dev' : getUserEmail();\n  if (!email) {\n    await telemetry.record('feature_used', {\n      feature: 'promptForEmailUnverified',\n    });\n    const emailSchema = z.string().email('Please enter a valid email address');\n    email = await input({\n      message: 'Redteam evals require email verification. Please enter your work email:',\n      validate: (input: string) => {\n        const result = emailSchema.safeParse(input);\n        return result.success || result.error.errors[0].message;\n      },\n    });\n    setUserEmail(email);\n    await telemetry.record('feature_used', {\n      feature: 'userCompletedPromptForEmailUnverified',\n    });\n  }\n  await telemetry.saveConsent(email, {\n    source: 'promptForEmailUnverified',\n  });\n}\n\nexport async function checkEmailStatusOrExit() {\n  const result = await checkEmailStatus();\n\n  if (result.status === 'exceeded_limit') {\n    logger.error(\n      'You have exceeded the maximum cloud inference limit. Please contact inquiries@promptfoo.dev to upgrade your account.',\n    );\n    process.exit(1);\n  }\n\n  if (result.status === 'show_usage_warning' && result.message) {\n    const border = '='.repeat(TERMINAL_MAX_WIDTH);\n    logger.info(chalk.yellow(border));\n    logger.warn(chalk.yellow(result.message));\n    logger.info(chalk.yellow(border));\n  }\n}\n"],"names":["checkEmailStatus","checkEmailStatusOrExit","getAuthor","getUserEmail","getUserId","isLoggedIntoCloud","promptForEmailUnverified","setUserEmail","globalConfig","readGlobalConfig","id","newId","randomUUID","writeGlobalConfig","account","email","config","writeGlobalConfigPartial","getEnvString","userEmail","isCI","status","hasEmail","message","resp","fetchWithTimeout","encodeURIComponent","undefined","data","json","e","logger","debug","default","telemetry","record","feature","emailSchema","z","string","input","validate","result","safeParse","success","error","errors","saveConsent","source","process","exit","border","repeat","TERMINAL_MAX_WIDTH","info","chalk","yellow","warn"],"mappings":";;;;;;;;;;;QAuDsBA;eAAAA;;QAkEAC;eAAAA;;QAtFNC;eAAAA;;QAVAC;eAAAA;;QAZAC;eAAAA;;QA0BAC;eAAAA;;QAyDMC;eAAAA;;QAlENC;eAAAA;;;wBA9BW;8DAET;8DACA;qBACA;2BACiB;wBACA;+DAChB;uBACc;8BAC6C;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;AAIvE,SAASH;IACd,IAAII,eAAeC,IAAAA,8BAAgB;IACnC,IAAI,CAACD,cAAcE,IAAI;QACrB,MAAMC,QAAQC,IAAAA,kBAAU;QACxBJ,eAAe;YAAE,GAAGA,YAAY;YAAEE,IAAIC;QAAM;QAC5CE,IAAAA,+BAAiB,EAACL;QAClB,OAAOG;IACT;IAEA,OAAOH,aAAaE,EAAE;AACxB;AAEO,SAASP;IACd,MAAMK,eAAeC,IAAAA,8BAAgB;IACrC,OAAOD,cAAcM,SAASC,SAAS;AACzC;AAEO,SAASR,aAAaQ,KAAa;IACxC,MAAMC,SAAgC;QAAEF,SAAS;YAAEC;QAAM;IAAE;IAC3DE,IAAAA,sCAAwB,EAACD;AAC3B;AAEO,SAASd;IACd,OAAOgB,IAAAA,oBAAY,EAAC,uBAAuBf,kBAAkB;AAC/D;AAEO,SAASE;IACd,MAAMc,YAAYhB;IAClB,OAAO,CAAC,CAACgB,aAAa,CAACC,IAAAA,YAAI;AAC7B;AAaO,eAAepB;IACpB,MAAMmB,YAAYC,IAAAA,YAAI,MAAK,iCAAiCjB;IAE5D,IAAI,CAACgB,WAAW;QACd,OAAO;YACLE,QAAQ;YACRC,UAAU;YACVC,SAAS;QACX;IACF;IAEA,IAAI;QACF,MAAMC,OAAO,MAAMC,IAAAA,uBAAgB,EACjC,CAAC,iDAAiD,EAAEC,mBAAmBP,YAAY,EACnFQ,WACA;