+{"version":3,"sources":["/workspace/repo/src/providers/mistral.ts"],"sourcesContent":["import { fetchWithCache, getCache, isCacheEnabled } from '../cache';\nimport { getEnvString } from '../envars';\nimport logger from '../logger';\nimport { calculateCost, parseChatPrompt, REQUEST_TIMEOUT_MS } from './shared';\n\nimport type { EnvVarKey } from '../envars';\nimport type {\n  ApiProvider,\n  CallApiContextParams,\n  ProviderEmbeddingResponse,\n  ProviderResponse,\n  TokenUsage,\n} from '../types/index';\nimport type { EnvOverrides } from '../types/env';\n\nconst MISTRAL_CHAT_MODELS = [\n  ...['open-mistral-7b', 'mistral-tiny', 'mistral-tiny-2312'].map((id) => ({\n    id,\n    cost: {\n      input: 0.25 / 1000000,\n      output: 0.25 / 1000000,\n    },\n  })),\n  ...[\n    'open-mistral-nemo',\n    'open-mistral-nemo-2407',\n    'mistral-tiny-2407',\n    'mistral-tiny-latest',\n  ].map((id) => ({\n    id,\n    cost: {\n      input: 0.3 / 1000000,\n      output: 0.3 / 1000000,\n    },\n  })),\n  ...['mistral-small-2402', 'mistral-small-latest'].map((id) => ({\n    id,\n    cost: {\n      input: 1 / 1000000,\n      output: 3 / 1000000,\n    },\n  })),\n  ...['mistral-medium-2312', 'mistral-medium', 'mistral-medium-latest'].map((id) => ({\n    id,\n    cost: {\n      input: 2.7 / 1000000,\n      output: 8.1 / 1000000,\n    },\n  })),\n  {\n    id: 'mistral-large-2402',\n    cost: {\n      input: 4 / 1000000,\n      output: 12 / 1000000,\n    },\n  },\n  ...['mistral-large-2407', 'mistral-large-latest'].map((id) => ({\n    id,\n    cost: {\n      input: 3 / 1000000,\n      output: 9 / 1000000,\n    },\n  })),\n  ...['codestral-2405', 'codestral-latest'].map((id) => ({\n    id,\n    cost: {\n      input: 1 / 1000000,\n      output: 3 / 1000000,\n    },\n  })),\n  ...['codestral-mamba-2407', 'open-codestral-mamba', 'codestral-mamba-latest'].map((id) => ({\n    id,\n    cost: {\n      input: 0.25 / 1000000,\n      output: 0.25 / 1000000,\n    },\n  })),\n  ...['open-mixtral-8x7b', 'mistral-small', 'mistral-small-2312'].map((id) => ({\n    id,\n    cost: {\n      input: 0.7 / 1000000,\n      output: 0.7 / 1000000,\n    },\n  })),\n  ...['open-mixtral-8x22b', 'open-mixtral-8x22b-2404'].map((id) => ({\n    id,\n    cost: {\n      input: 2 / 1000000,\n      output: 6 / 1000000,\n    },\n  })),\n  // New Magistral models - reasoning models announced June 2025\n  {\n    id: 'magistral-small-2506',\n    cost: {\n      input: 0.5 / 1000000,\n      output: 1.5 / 1000000,\n    },\n  },\n  {\n    id: 'magistral-medium-2506',\n    cost: {\n      input: 2 / 1000000,\n      output: 5 / 1000000,\n    },\n  },\n  // Also support latest aliases\n  {\n    id: 'magistral-small-latest',\n    cost: {\n      input: 0.5 / 1000000,\n      output: 1.5 / 1000000,\n    },\n  },\n  {\n    id: 'magistral-medium-latest',\n    cost: {\n      input: 2 / 1000000,\n      output: 5 / 1000000,\n    },\n  },\n  // Multimodal model\n  {\n    id: 'pixtral-12b',\n    cost: {\n      input: 0.15 / 1000000,\n      output: 0.15 / 1000000,\n    },\n  },\n];\n\nconst MISTRAL_EMBEDDING_MODELS = [\n  {\n    id: 'mistral-embed',\n    cost: {\n      input: 0.1 / 1000000,\n      output: 0.1 / 1000000,\n    },\n  },\n];\n\ninterface MistralChatCompletionOptions {\n  apiKey?: string;\n  apiKeyEnvar?: string;\n  apiHost?: string;\n  apiBaseUrl?: string;\n  temperature?: number;\n  top_p?: number;\n  max_tokens?: number;\n  safe_prompt?: boolean;\n  random_seed?: number;\n  response_format?: { type: 'json_object' };\n  cost?: number;\n}\n\nfunction getTokenUsage(data: any, cached: boolean): Partial<TokenUsage> {\n  if (data.usage) {\n    if (cached) {\n      return { cached: data.usage.total_tokens, total: data.usage.total_tokens };\n    } else {\n      return {\n        total: data.usage.total_tokens,\n        prompt: data.usage.prompt_tokens || 0,\n        completion: data.usage.completion_tokens || 0,\n      };\n    }\n  }\n  return {};\n}\n\nfunction calculateMistralCost(\n  modelName: string,\n  config: MistralChatCompletionOptions,\n  promptTokens?: number,\n  completionTokens?: number,\n): number | undefined {\n  return calculateCost(modelName, config, promptTokens, completionTokens, [\n    ...MISTRAL_CHAT_MODELS,\n    ...MISTRAL_EMBEDDING_MODELS,\n  ]);\n}\n\nexport class MistralChatCompletionProvider implements ApiProvider {\n  modelName: string;\n  config: MistralChatCompletionOptions;\n  env?: EnvOverrides;\n\n  static MISTRAL_CHAT_MODELS = MISTRAL_CHAT_MODELS;\n\n  static MISTRAL_CHAT_MODELS_NAMES = MISTRAL_CHAT_MODELS.map((model) => model.id);\n\n  constructor(\n    modelName: string,\n    options: { id?: string; config?: MistralChatCompletionOptions; env?: EnvOverrides } = {},\n  ) {\n    if (!MistralChatCompletionProvider.MISTRAL_CHAT_MODELS_NAMES.includes(modelName)) {\n      logger.warn(`Using unknown Mistral chat model: ${modelName}`);\n    }\n    const { id, config, env } = options;\n    this.env = env;\n    this.modelName = modelName;\n    this.id = id ? () => id : this.id;\n    this.config = config || {};\n  }\n\n  id(): string {\n    return `mistral:${this.modelName}`;\n  }\n\n  toString(): string {\n    return `[Mistral Provider ${this.modelName}]`;\n  }\n\n  getApiUrlDefault(): string {\n    return 'https://api.mistral.ai/v1';\n  }\n\n  getApiUrl(): string {\n    const apiHost =\n      this.config.apiHost || this.env?.MISTRAL_API_HOST || getEnvString('MISTRAL_API_HOST');\n    if (apiHost) {\n      return `https://${apiHost}/v1`;\n    }\n    return (\n      this.config.apiBaseUrl ||\n      this.env?.MISTRAL_API_BASE_URL ||\n      getEnvString('MISTRAL_API_BASE_URL') ||\n      this.getApiUrlDefault()\n    );\n  }\n\n  getApiKey(): string | undefined {\n    logger.debug(`Mistral apiKeyenvar: ${this.config.apiKeyEnvar}`);\n    const apiKeyCandidate =\n      this.config?.apiKey ||\n      (this.config?.apiKeyEnvar\n        ? getEnvString(this.config.apiKeyEnvar as EnvVarKey) ||\n          this.env?.[this.config.apiKeyEnvar as keyof EnvOverrides]\n        : undefined) ||\n      this.env?.MISTRAL_API_KEY ||\n      getEnvString('MISTRAL_API_KEY');\n    return apiKeyCandidate;\n  }\n\n  async callApi(prompt: string, context?: CallApiContextParams): Promise<ProviderResponse> {\n    if (!this.getApiKey()) {\n      throw new Error(\n        'Mistral API key is not set. Set the MISTRAL_API_KEY environment variable or add `apiKey` or `apiKeyEnvar` to the provider config.',\n      );\n    }\n\n    // Merge configs from the provider and the prompt\n    const config = {\n      ...this.config,\n      ...context?.prompt?.config,\n    };\n\n    const messages = parseChatPrompt(prompt, [{ role: 'user', content: prompt }]);\n\n    const params = {\n      model: this.modelName,\n      messages,\n      temperature: config?.temperature,\n      top_p: config?.top_p || 1,\n      max_tokens: config?.max_tokens || 1024,\n      safe_prompt: config?.safe_prompt || false,\n      random_seed: config?.random_seed || null,\n      ...(config.response_format ? { response_format: config.response_format } : {}),\n    };\n\n    const cacheKey = `mistral:${JSON.stringify(params)}`;\n    if (isCacheEnabled()) {\n      const cache = getCache();\n      if (cache) {\n        const cachedResult = await cache.get<ProviderResponse>(cacheKey);\n        if (cachedResult) {\n          logger.debug(`Returning cached response for ${prompt}: ${JSON.stringify(cachedResult)}`);\n          return {\n            ...cachedResult,\n            tokenUsage: {\n              ...cachedResult.tokenUsage,\n              cached: cachedResult.tokenUsage?.total,\n            },\n          };\n        }\n      }\n    }\n\n    const url = `${this.getApiUrl()}/chat/completions`;\n    logger.debug(`Mistral API request: ${url} ${JSON.stringify(params)}`);\n\n    let data,\n      cached = false;\n\n    try {\n      ({ data, cached } = (await fetchWithCache(\n        url,\n        {\n          method: 'POST',\n          headers: {\n            'Content-Type': 'application/json',\n            Authorization: `Bearer ${this.getApiKey()}`,\n          },\n          body: JSON.stringify(params),\n        },\n        REQUEST_TIMEOUT_MS,\n      )) as unknown as { data: any; cached: boolean });\n    } catch (err) {\n      return {\n        error: `API call error: ${String(err)}`,\n      };\n    }\n\n    logger.debug(`Mistral API response: ${JSON.stringify(data)}`);\n\n    if (data.error) {\n      return {\n        error: `API call error: ${data.error}`,\n      };\n    }\n    if (!data.choices || !data.choices[0] || !data.choices[0].message.content) {\n      return {\n        error: `Malformed response data: ${JSON.stringify(data)}`,\n      };\n    }\n\n    const result: ProviderResponse = {\n      output: data.choices[0].message.content,\n      tokenUsage: getTokenUsage(data, cached),\n      cached,\n      cost: calculateMistralCost(\n        this.modelName,\n        config,\n        data.usage?.prompt_tokens,\n        data.usage?.completion_tokens,\n      ),\n    };\n\n    if (isCacheEnabled()) {\n      try {\n        await getCache().set(cacheKey, result);\n      } catch (err) {\n        logger.error(`Failed to cache response: ${String(err)}`);\n      }\n    }\n\n    return result;\n  }\n}\n\nexport class MistralEmbeddingProvider implements ApiProvider {\n  modelName: string;\n  config: MistralChatCompletionOptions;\n  env?: EnvOverrides;\n\n  constructor(\n    options: { config?: MistralChatCompletionOptions; id?: string; env?: EnvOverrides } = {},\n  ) {\n    const { config, env } = options;\n    this.modelName = 'mistral-embed';\n    this.config = config || {};\n    this.env = env;\n  }\n\n  id(): string {\n    return `mistral:embedding:${this.modelName}`;\n  }\n\n  toString(): string {\n    return `[Mistral Embedding Provider ${this.modelName}]`;\n  }\n\n  getApiUrlDefault(): string {\n    return 'https://api.mistral.ai/v1';\n  }\n\n  getApiUrl(): string {\n    const apiHost =\n      this.config.apiHost || this.env?.MISTRAL_API_HOST || getEnvString('MISTRAL_API_HOST');\n    if (apiHost) {\n      return `https://${apiHost}/v1`;\n    }\n    return (\n      this.config.apiBaseUrl ||\n      this.env?.MISTRAL_API_BASE_URL ||\n      getEnvString('MISTRAL_API_BASE_URL') ||\n      this.getApiUrlDefault()\n    );\n  }\n\n  getApiKey(): string | undefined {\n    logger.debug(`Mistral apiKeyenvar: ${this.config.apiKeyEnvar}`);\n    const apiKeyCandidate =\n      this.config?.apiKey ||\n      (this.config?.apiKeyEnvar\n        ? getEnvString(this.config.apiKeyEnvar as EnvVarKey) ||\n          this.env?.[this.config.apiKeyEnvar as keyof EnvOverrides]\n        : undefined) ||\n      this.env?.MISTRAL_API_KEY ||\n      getEnvString('MISTRAL_API_KEY');\n    return apiKeyCandidate;\n  }\n\n  async callApi(text: string): Promise<ProviderResponse> {\n    try {\n      const embeddingResponse = await this.callEmbeddingApi(text);\n      return {\n        output: JSON.stringify(embeddingResponse.embedding),\n        tokenUsage: embeddingResponse.tokenUsage,\n        cost: embeddingResponse.cost,\n      };\n    } catch (err) {\n      return {\n        error: `Embedding API call error: ${String(err)}`,\n      };\n    }\n  }\n\n  async callEmbeddingApi(text: string): Promise<ProviderEmbeddingResponse> {\n    if (!this.getApiKey()) {\n      throw new Error('Mistral API key must be set for embedding');\n    }\n\n    const body = {\n      model: this.modelName,\n      input: text,\n    };\n\n    const url = `${this.getApiUrl()}/embeddings`;\n\n    let data;\n    let cached = false;\n\n    try {\n      ({ data, cached } = (await fetchWithCache(\n        url,\n        {\n          method: 'POST',\n          headers: {\n            'Content-Type': 'application/json',\n            Authorization: `Bearer ${this.getApiKey()}`,\n          },\n          body: JSON.stringify(body),\n        },\n        REQUEST_TIMEOUT_MS,\n      )) as unknown as { data: any; cached: boolean });\n    } catch (err) {\n      logger.error(`API call error: ${err}`);\n      throw err;\n    }\n\n    try {\n      const embedding = data?.data?.[0]?.embedding;\n      if (!embedding) {\n        throw new Error('No embedding found in Mistral Embedding API response');\n      }\n      const tokenUsage = getTokenUsage(data, cached);\n      const promptTokens = tokenUsage.prompt || 0;\n      const completionTokens = 0; // Embeddings don't have completion tokens\n      return {\n        embedding,\n        tokenUsage: {\n          ...tokenUsage,\n          completion: completionTokens,\n        },\n        cost: calculateMistralCost(this.modelName, this.config, promptTokens, completionTokens),\n      };\n    } catch (err) {\n      logger.error(data.error?.message || 'Unknown error');\n      throw err;\n    }\n  }\n}\n"],"names":["MistralChatCompletionProvider","MistralEmbeddingProvider","MISTRAL_CHAT_MODELS","map","id","cost","input","output","MISTRAL_EMBEDDING_MODELS","getTokenUsage","data","cached","usage","total_tokens","total","prompt","prompt_tokens","completion","completion_tokens","calculateMistralCost","modelName","config","promptTokens","completionTokens","calculateCost","env","MISTRAL_CHAT_MODELS_NAMES","model","options","includes","logger","warn","toString","getApiUrlDefault","getApiUrl","apiHost","MISTRAL_API_HOST","getEnvString","apiBaseUrl","MISTRAL_API_BASE_URL","getApiKey","debug","apiKeyEnvar","apiKeyCandidate","apiKey","undefined","MISTRAL_API_KEY","callApi","context","Error","messages","parseChatPrompt","role","content","params","temperature","top_p","max_tokens","safe_prompt","random_seed","response_format","cacheKey","JSON","stringify","isCacheEnabled","cache","getCache","cachedResult","get","tokenUsage","url","fetchWithCache","method","headers","Authorization","body","REQUEST_TIMEOUT_MS","err","error","String","choices","message","result","set","text","embeddingResponse","callEmbeddingApi","embedding"],"mappings":";;;;;;;;;;;QAsLaA;eAAAA;;QAwKAC;eAAAA;;;uBA9V4C;wBAC5B;+DACV;wBACgD;;;;;;AAYnE,MAAMC