body: JSON.stringify(payload),\n        },\n        REQUEST_TIMEOUT_MS,\n      );\n\n      logger.debug(\n        `Got Likert jailbreak generation result for case ${Number(index) + 1}: ${JSON.stringify(\n          data,\n        )}`,\n      );\n      if (data.error) {\n        logger.error(`[jailbreak:likert] Error in Likert generation: ${data.error}}`);\n        logger.debug(`[jailbreak:likert] Response: ${JSON.stringify(data)}`);\n        return;\n      }\n\n      const likertTestCases = data.modifiedPrompts.map((modifiedPrompt: string) => {\n        const originalText = String(testCase.vars![injectVar]);\n        return {\n          ...testCase,\n          vars: {\n            ...testCase.vars,\n            [injectVar]: modifiedPrompt,\n          },\n          assert: testCase.assert?.map((assertion) => ({\n            ...assertion,\n            metric: `${assertion.metric}/Likert`,\n          })),\n          metadata: {\n            ...testCase.metadata,\n            strategyId: 'jailbreak:likert',\n            originalText,\n          },\n        };\n      });\n\n      allResults = allResults.concat(likertTestCases);\n\n      if (progressBar) {\n        progressBar.increment(1);\n      } else {\n        logger.debug(`Processed case ${Number(index) + 1} of ${testCases.length}`);\n      }\n    });\n\n    if (progressBar) {\n      progressBar.stop();\n    }\n\n    return allResults;\n  } catch (error) {\n    if (progressBar) {\n      progressBar.stop();\n    }\n    logger.error(`Error in Likert generation: ${error}`);\n    return [];\n  }\n}\n\nexport async function addLikertTestCases(\n  testCases: TestCase[],\n  injectVar: string,\n  config: Record<string, unknown>,\n): Promise<TestCase[]> {\n  if (neverGenerateRemote()) {\n    throw new Error('Likert jailbreak strategy requires remote generation to be enabled');\n  }\n\n  const likertTestCases = await generateLikertPrompts(testCases, injectVar, config);\n  if (likertTestCases.length === 0) {\n    logger.warn('No Likert jailbreak test cases were generated');\n  }\n\n  return likertTestCases;\n}\n"],"names":["addLikertTestCases","generateLikertPrompts","testCases","injectVar","config","progressBar","concurrency","allResults","logger","level","SingleBar","format","hideCursor","gracefulExit","Presets","shades_classic","start","length","async","forEachOfLimit","testCase","index","debug","JSON","stringify","invariant","vars","payload","task","prompt","plugin","metadata","plugins","join","pluginId","email","getUserEmail","data","fetchWithCache","getRemoteGenerationUrl","method","headers","body","REQUEST_TIMEOUT_MS","Number","error","likertTestCases","modifiedPrompts","map","modifiedPrompt","originalText","String","assert","assertion","metric","strategyId","concat","increment","stop","neverGenerateRemote","Error","warn"],"mappings":";;;;+BAoHsBA;;;eAAAA;;;8DApHJ;6BACiB;uBACJ;0BACF;+DACV;wBACgB;kEACb;kCACsC;;;;;;AAI5D,eAAeC,sBACbC,SAAqB,EACrBC,SAAiB,EACjBC,MAA2B;IAE3B,IAAIC;IACJ,IAAI;QACF,MAAMC,cAAc;QACpB,IAAIC,aAAyB,EAAE;QAE/B,IAAIC,eAAM,CAACC,KAAK,KAAK,SAAS;YAC5BJ,cAAc,IAAIK,sBAAS,CACzB;gBACEC,QACE;gBACFC,YAAY;gBACZC,cAAc;YAChB,GACAC,oBAAO,CAACC,cAAc;YAExBV,YAAYW,KAAK,CAACd,UAAUe,MAAM,EAAE;QACtC;QAEA,MAAMC,cAAK,CAACC,cAAc,CAACjB,WAAWI,aAAa,OAAOc,UAAUC;YAClEb,eAAM,CAACc,KAAK,CAAC,CAAC,+BAA+B,EAAEC,KAAKC,SAAS,CAACJ,WAAW;YACzEK,IAAAA,kBAAS,EACPL,SAASM,IAAI,EACb,CAAC,2CAA2C,EAAEH,KAAKC,SAAS,CAACJ,WAAW;YAG1E,MAAMO,UAAU;gBACdC,MAAM;gBACNC,QAAQT,SAASM,IAAI,CAACvB,UAAU;gBAChCkB;gBACAS,QAAQV,SAASW,QAAQ,EAAEC,SAASC,KAAK,QAAQb,SAASW,QAAQ,EAAEG;gBACpE,GAAG9B,MAAM;gBACT+B,OAAOC,IAAAA,sBAAY;YACrB;YAEA,MAAM,EAAEC,IAAI,EAAE,GAAG,MAAMC,IAAAA,qBAAc,EACnCC,IAAAA,wCAAsB,KACtB;gBACEC,QAAQ;gBACRC,SAAS;oBACP,gBAAgB;gBAClB;gBACAC,MAAMnB,KAAKC,SAAS,CAACG;YACvB,GACAgB,0BAAkB;YAGpBnC,eAAM,CAACc,KAAK,CACV,CAAC,gDAAgD,EAAEsB,OAAOvB,SAAS,EAAE,EAAE,EAAEE,KAAKC,SAAS,CACrFa,OACC;YAEL,IAAIA,KAAKQ,KAAK,EAAE;gBACdrC,eAAM,CAACqC,KAAK,CAAC,CAAC,+CAA+C,EAAER,KAAKQ,KAAK,CAAC,CAAC,CAAC;gBAC5ErC,eAAM,CAACc,KAAK,CAAC,CAA