awPrompt: string;\n    renderedValue?: AssertionValue;\n  }): ResultSuggestion[] {\n    const noteValue = dedent`\n      Consider setting a maximum number of tokens for the response.\n    `;\n\n    return [\n      {\n        action: 'note',\n        type: 'divergent-repetition',\n        value: noteValue,\n      },\n    ];\n  }\n}\n"],"names":["DivergentRepetitionGrader","DivergentRepetitionPlugin","PLUGIN_ID","DEFAULT_EXAMPLES","dedent","RedteamPluginBase","id","getTemplate","getAssertions","prompt","type","metric","RedteamGraderBase","rubric","getSuggestions","rawPrompt","renderedValue","noteValue","action","value"],"mappings":"AAAA;;;CAGC;;;;;;;;;;;QA2EYA;eAAAA;;QA7CAC;eAAAA;;;+DA7BM;sBACkC;;;;;;AAIrD,MAAMC,YAAY;AAElB,MAAMC,mBAAmBC,IAAAA,eAAM,CAAA,CAAC;;;;;;;;;;;;;;;;;;;;AAoBhC,CAAC;AAEM,MAAMH,kCAAkCI,uBAAiB;IACrDC,KAAKJ,UAAU;IAExB,MAAgBK,cAA+B;QAC7C,OAAOH,IAAAA,eAAM,CAAA,CAAC;;;;;;;;;;;;;;;;;;;;;;IAsBd,EAAED,iBAAiB;;;;;;IAMnB,CAAC;IACH;IAEUK,cAAcC,MAAc,EAAe;QACnD,OAAO;YACL;gBACEC,MAAMR;gBACNS,QAAQ;YACV;SACD;IACH;AACF;AAEO,MAAMX,kCAAkCY,uBAAiB;IACrDN,KAAKJ,UAAU;IACxBW,SAAST,IAAAA,eAAM,CAAA,CAAC;;;;;;;;;;;;;;;;;;;;;;;;;;;EA2BhB,CAAC,CAAC;IAEFU,eAAe,EACbC,SAAS,EACTC,aAAa,EAId,EAAsB;QACrB,MAAMC,YAAYb,IAAAA,eAAM,CAAA,CAAC;;IAEzB,CAAC;QAED,OAAO;YACL;gBACEc,QAAQ;gBACRR,MAAM;gBACNS,OAAOF;YACT;SACD;IACH;AACF"}
